import {orbitPlan,orbitSources,bodies} from './orbits.js';
import {t} from './i18n.js';
export function mountLab(container,mission,cfg,close,apply){
 let altitude=cfg.orbit?.altitude??100,comparison=null;
 function render(){const p=orbitPlan(mission.id,altitude,cfg.dryMass??cfg.mass),base=orbitPlan(mission.id,100,cfg.dryMass??cfg.mass),radius=65,outer=65+altitude/20;
 container.innerHTML=`<section class="library orbit-lab"><div class="library-top"><div><div class="eyebrow">MISSION DESIGN / EXPERIMENT 01</div><h1>Orbital laboratory</h1></div><button id="lab-close" class="secondary">RETURN ↙</button></div><p>Predict, change one variable, then compare. Raising a circular orbit reduces speed but increases its period.</p><div class="lab-grid"><div><svg viewBox="0 0 360 300" role="img" aria-label="Circular orbit comparison"><defs><radialGradient id="planet-light"><stop stop-color="#91aeae"/><stop offset="1" stop-color="#263b52"/></radialGradient></defs><circle cx="180" cy="150" r="${radius}" fill="url(#planet-light)"/><circle cx="180" cy="150" r="70" fill="none" stroke="#759696" stroke-dasharray="4 6"/><circle cx="180" cy="150" r="${outer}" fill="none" stroke="#8ff0ce" stroke-width="2"/><g class="orbit-satellite" style="--period:${p.period/base.period*8}s"><circle cx="${180+outer}" cy="150" r="6" fill="#ffd4a1"/></g><text x="180" y="155" text-anchor="middle" fill="white">${t(mission.name)}</text></svg><p>Diagram not to scale.</p><label for="orbit-height">Target altitude</label><div class="altitude-value" data-no-translate>${altitude} km</div><input id="orbit-height" type="range" min="100" max="1200" step="50" value="${altitude}"><p>Starting orbit: 100 km. Animation is accelerated; displayed times are physical seconds.</p></div><div><div class="stat-line">Orbital speed <b data-no-translate>${p.speed.toFixed(3)} km/s</b></div><div class="stat-line">Orbital period <b data-no-translate>${(p.period/60).toFixed(1)} min</b></div><div class="stat-line">First burn <b data-no-translate>${p.burn1.toFixed(1)} m/s</b></div><div class="stat-line">Second burn <b data-no-translate>${p.burn2.toFixed(1)} m/s</b></div><div class="stat-line">Coast time <b data-no-translate>${(p.coast/60).toFixed(1)} min</b></div><div class="stat-line">Propellant required <b data-no-translate>${p.propellant.toFixed(1)} kg</b></div><div class="stat-line">Wet mass / launch capacity <b class="${p.wetMass>cfg.launcher.capacity?'bad':''}" data-no-translate>${p.wetMass.toFixed(1)} / ${cfg.launcher.capacity} kg</b></div><p>${p.wetMass>cfg.launcher.capacity?'Mass constraint failed. Reduce altitude or redesign the launch system.':'Mass constraint passed. A real mission still needs reserves and a complete trajectory review.'}</p><div class="buttons"><button id="lab-compare" class="secondary">SAVE COMPARISON</button><button id="lab-apply" class="primary">APPLY FLIGHT PLAN →</button></div></div></div>${comparison?`<div class="comparison"><h3>Design comparison</h3><p data-no-translate>${comparison.altitude} → ${altitude} km · Δv ${comparison.deltaV.toFixed(1)} → ${p.deltaV.toFixed(1)} m/s · ${comparison.propellant.toFixed(1)} → ${p.propellant.toFixed(1)} kg</p><p>Higher altitude costs propellant in this transfer. Compare that cost with the observing geometry your science objective needs.</p></div>`:''}<details><summary>Equations and assumptions</summary><p data-no-translate>v = √(μ/r) · T = 2π√(r³/μ)<br>Δv₁ = √(μ/r₁)[√(2r₂/(r₁+r₂)) − 1]<br>Δv₂ = √(μ/r₂)[1 − √(2r₁/(r₁+r₂))]<br>mₚ = m_dry [exp(Δv/(Isp·g₀)) − 1]<br>μ = ${bodies[mission.id].mu} km³/s² · R = ${bodies[mission.id].radius} km · Isp = 220 s · g₀ = 9.80665 m/s²</p><p>Two-body, circular, coplanar orbits and instantaneous burns. No launch from Earth, atmosphere, third-body gravity or operational reserves. Europa is an idealized exercise; Jupiter is omitted. Hardware mass and engine efficiency are illustrative. Applying a plan adds transfer propellant to launch mass. Surface combat and contact windows remain fictional.</p></details><p class="story-note">${orbitSources.map((url,i)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${['JPL / GM + satellite radii','JPL / planetary radii','NASA / trajectories'][i]}</a>`).join(' · ')}</p></section>`;
 container.querySelector('#lab-close').onclick=close;container.querySelector('#lab-apply').onclick=()=>apply?.(altitude);
 const slider=container.querySelector('#orbit-height');slider.onchange=()=>{altitude=Number(slider.value);render();container.querySelector('#orbit-height').focus();};slider.oninput=()=>container.querySelector('.altitude-value').textContent=slider.value+' km';
 container.querySelector('#lab-compare').onclick=()=>{comparison=p;render();};
 }
 render();
}
